  1→package jlsm.table.internal;
  2→
  3→import java.lang.foreign.Arena;
  4→import java.lang.foreign.MemorySegment;
  5→import java.lang.foreign.ValueLayout;
  6→import java.util.Arrays;
  7→import java.util.Objects;
  8→
  9→/**
 10→ * Contract: Arena-backed off-heap storage for encryption key material. Accepts a {@code byte[]}
 11→ * key, copies it to an off-heap {@link MemorySegment}, and zeros the caller's copy. On
 12→ * {@link #close()}, the key segment is zeroed ({@code fill(0)}) and the arena is closed.
 13→ *
 14→ * <p>
 15→ * Uses {@link Arena#ofShared()} to allow concurrent read access from multiple table reader threads.
 16→ * Close is idempotent via a {@code volatile boolean}.
 17→ *
 18→ * <p>
 19→ * Governed by: .kb/systems/security/jvm-key-handling-patterns.md
 20→ */
 21→public final class EncryptionKeyHolder implements AutoCloseable {
 22→
 23→    private static final int KEY_256_BYTES = 32;
 24→    private static final int KEY_512_BYTES = 64;
 25→
 26→    private final Arena arena;
 27→    private final MemorySegment keySegment;
 28→    private final int keyLength;
 29→    private volatile boolean closed;
 30→
 31→    private EncryptionKeyHolder(Arena arena, MemorySegment keySegment, int keyLength) {
 32→        assert arena != null : "arena must not be null";
 33→        assert keySegment != null : "keySegment must not be null";
 34→        assert keyLength == KEY_256_BYTES || keyLength == KEY_512_BYTES
 35→                : "keyLength must be 32 or 64";
 36→        this.arena = arena;
 37→        this.keySegment = keySegment;
 38→        this.keyLength = keyLength;
 39→        this.closed = false;
 40→    }
 41→
 42→    /**
 43→     * Creates a new key holder from the given key material. The caller's array is zeroed after the
 44→     * key is copied to off-heap memory.
 45→     *
 46→     * @param keyMaterial the raw key bytes; must be 32 or 64 bytes
 47→     * @return a new key holder owning the off-heap copy
 48→     * @throws NullPointerException if keyMaterial is null
 49→     * @throws IllegalArgumentException if keyMaterial is not 32 or 64 bytes
 50→     */
 51→    public static EncryptionKeyHolder of(byte[] keyMaterial) {
 52→        Objects.requireNonNull(keyMaterial, "keyMaterial must not be null");
 53→        if (keyMaterial.length != KEY_256_BYTES && keyMaterial.length != KEY_512_BYTES) {
 54→            throw new IllegalArgumentException(
 55→                    "Key must be 32 or 64 bytes (256 or 512 bit), got " + keyMaterial.length);
 56→        }
 57→
 58→        final Arena arena = Arena.ofShared();
 59→        final MemorySegment segment = arena.allocate(keyMaterial.length);
 60→        MemorySegment.copy(keyMaterial, 0, segment, ValueLayout.JAVA_BYTE, 0, keyMaterial.length);
 61→
 62→        // Zero the caller's copy
 63→        Arrays.fill(keyMaterial, (byte) 0);
 64→
 65→        return new EncryptionKeyHolder(arena, segment, keyMaterial.length);
 66→    }
 67→
 68→    /**
 69→     * Returns a temporary byte[] copy of the key material. Callers must zero this array after use.
 70→     *
 71→     * @return a fresh byte[] copy of the key
 72→     * @throws IllegalStateException if this holder has been closed
 73→     */
 74→    public byte[] getKeyBytes() {
 75→        ensureOpen();
 76→        final byte[] copy = new byte[keyLength];
 77→        MemorySegment.copy(keySegment, ValueLayout.JAVA_BYTE, 0, copy, 0, keyLength);
 78→        return copy;
 79→    }
 80→
 81→    /**
 82→     * Returns a read-only view of the key segment.
 83→     *
 84→     * @return the off-heap key memory segment
 85→     * @throws IllegalStateException if this holder has been closed
 86→     */
 87→    public MemorySegment keySegment() {
 88→        ensureOpen();
 89→        return keySegment.asReadOnly();
 90→    }
 91→
 92→    /**
 93→     * Returns the key length in bytes.
 94→     *
 95→     * @return key length
 96→     * @throws IllegalStateException if this holder has been closed
 97→     */
 98→    public int keyLength() {
 99→        ensureOpen();
100→        return keyLength;
101→    }
102→
103→    @Override
104→    public void close() {
105→        if (closed) {
106→            return;
107→        }
108→        closed = true;
109→        // Zero the key material before releasing the arena
110→        keySegment.fill((byte) 0);
111→        arena.close();
112→    }
113→
114→    private void ensureOpen() {
115→        if (closed) {
116→            throw new IllegalStateException("EncryptionKeyHolder has been closed");
117→        }
118→    }
119→}
