package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import jlsm.table.internal.AesSivEncryptor;
import jlsm.table.internal.EncryptionKeyHolder;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;

/**
 * Tests for {@link AesSivEncryptor}: deterministic AES-SIV encryption per RFC 5297.
 */
class AesSivEncryptorTest {

    private EncryptionKeyHolder keyHolder;

    private static byte[] key512() {
        final byte[] key = new byte[64];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 1);
        }
        return key;
    }

    private static byte[] key512Alt() {
        final byte[] key = new byte[64];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 0x80);
        }
        return key;
    }

    @BeforeEach
    void setUp() {
        keyHolder = EncryptionKeyHolder.of(key512());
    }

    @AfterEach
    void tearDown() {
        keyHolder.close();
    }

    // ── Round-trip ──────────────────────────────────────────────────────────

    @Test
    void encryptDecrypt_roundTrip() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "Hello, AES-SIV!".getBytes();
        final byte[] ad = "context".getBytes();

        final byte[] ciphertext = encryptor.encrypt(plaintext, ad);
        final byte[] recovered = encryptor.decrypt(ciphertext, ad);

        assertArrayEquals(plaintext, recovered);
    }

    @Test
    void encryptDecrypt_roundTrip_emptyAssociatedData() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "No AD test".getBytes();

        final byte[] ciphertext = encryptor.encrypt(plaintext, new byte[0]);
        final byte[] recovered = encryptor.decrypt(ciphertext, new byte[0]);

        assertArrayEquals(plaintext, recovered);
    }

    @Test
    void encryptDecrypt_roundTrip_nullAssociatedData() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "Null AD test".getBytes();

        final byte[] ciphertext = encryptor.encrypt(plaintext, null);
        final byte[] recovered = encryptor.decrypt(ciphertext, null);

        assertArrayEquals(plaintext, recovered);
    }

    @Test
    void encryptDecrypt_roundTrip_emptyPlaintext() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = new byte[0];

        final byte[] ciphertext = encryptor.encrypt(plaintext, null);
        final byte[] recovered = encryptor.decrypt(ciphertext, null);

        assertArrayEquals(plaintext, recovered);
    }

    @Test
    void encryptDecrypt_roundTrip_largePlaintext() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = new byte[4096];
        Arrays.fill(plaintext, (byte) 0xAB);

        final byte[] ciphertext = encryptor.encrypt(plaintext, null);
        final byte[] recovered = encryptor.decrypt(ciphertext, null);

        assertArrayEquals(plaintext, recovered);
    }

    // ── Determinism ─────────────────────────────────────────────────────────

    @Test
    void encrypt_isDeterministic_samePlaintextAndAd() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "deterministic".getBytes();
        final byte[] ad = "same-ad".getBytes();

        final byte[] ct1 = encryptor.encrypt(plaintext, ad);
        final byte[] ct2 = encryptor.encrypt(plaintext, ad);

        assertArrayEquals(ct1, ct2, "Same plaintext + same AD must produce identical ciphertext");
    }

    @Test
    void encrypt_differentAd_producesDifferentCiphertext() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "same-plaintext".getBytes();

        final byte[] ct1 = encryptor.encrypt(plaintext, "ad-one".getBytes());
        final byte[] ct2 = encryptor.encrypt(plaintext, "ad-two".getBytes());

        assertFalse(Arrays.equals(ct1, ct2),
                "Different associated data must produce different ciphertext");
    }

    // ── Ciphertext expansion ────────────────────────────────────────────────

    @Test
    void encrypt_ciphertextIs16BytesLongerThanPlaintext() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "measure expansion".getBytes();

        final byte[] ciphertext = encryptor.encrypt(plaintext, null);

        assertEquals(plaintext.length + 16, ciphertext.length,
                "Ciphertext must be exactly 16 bytes longer (SIV tag)");
    }

    @Test
    void encrypt_emptyPlaintext_ciphertextIs16Bytes() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);

        final byte[] ciphertext = encryptor.encrypt(new byte[0], null);

        assertEquals(16, ciphertext.length,
                "Empty plaintext produces 16-byte ciphertext (SIV tag only)");
    }

    // ── Wrong key ───────────────────────────────────────────────────────────

    @Test
    void decrypt_wrongKey_throwsSecurityException() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        final byte[] plaintext = "secret".getBytes();
        final byte[] ad = "context".getBytes();
        final byte[] ciphertext = encryptor.encrypt(plaintext, ad);

        try (final EncryptionKeyHolder otherKey = EncryptionKeyHolder.of(key512Alt())) {
            final AesSivEncryptor otherEncryptor = new AesSivEncryptor(otherKey);
            assertThrows(SecurityException.class, () -> otherEncryptor.decrypt(ciphertext, ad),
                    "Decryption with wrong key must throw SecurityException");
        }
    }

    // ── Input validation ────────────────────────────────────────────────────

    @Test
    void encrypt_nullPlaintext_throwsNullPointerException() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        assertThrows(NullPointerException.class, () -> encryptor.encrypt(null, null));
    }

    @Test
    void decrypt_nullCiphertext_throwsNullPointerException() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        assertThrows(NullPointerException.class, () -> encryptor.decrypt(null, null));
    }

    @Test
    void decrypt_ciphertextTooShort_throwsIllegalArgumentException() {
        final AesSivEncryptor encryptor = new AesSivEncryptor(keyHolder);
        assertThrows(IllegalArgumentException.class,
                () -> encryptor.decrypt(new byte[15], null));
    }

    @Test
    void constructor_rejects256BitKey() {
        final byte[] smallKey = new byte[32];
        Arrays.fill(smallKey, (byte) 0x42);
        try (final EncryptionKeyHolder holder256 = EncryptionKeyHolder.of(smallKey)) {
            assertThrows(IllegalArgumentException.class, () -> new AesSivEncryptor(holder256));
        }
    }
}

package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import jlsm.table.internal.AesGcmEncryptor;
import jlsm.table.internal.EncryptionKeyHolder;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;

/**
 * Tests for {@link AesGcmEncryptor}: opaque AES-GCM authenticated encryption.
 */
class AesGcmEncryptorTest {

    private EncryptionKeyHolder keyHolder;

    private static byte[] key256() {
        final byte[] key = new byte[32];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 1);
        }
        return key;
    }

    private static byte[] key256Alt() {
        final byte[] key = new byte[32];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 0x80);
        }
        return key;
    }

    @BeforeEach
    void setUp() {
        keyHolder = EncryptionKeyHolder.of(key256());
    }

    @AfterEach
    void tearDown() {
        keyHolder.close();
    }

    // ── Round-trip ──────────────────────────────────────────────────────────

    @Test
    void encryptDecrypt_roundTrip() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = "Hello, AES-GCM!".getBytes();

        final byte[] ciphertext = encryptor.encrypt(plaintext);
        final byte[] recovered = encryptor.decrypt(ciphertext);

        assertArrayEquals(plaintext, recovered);
    }

    @Test
    void encryptDecrypt_roundTrip_emptyPlaintext() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = new byte[0];

        final byte[] ciphertext = encryptor.encrypt(plaintext);
        final byte[] recovered = encryptor.decrypt(ciphertext);

        assertArrayEquals(plaintext, recovered);
    }

    @Test
    void encryptDecrypt_roundTrip_largePlaintext() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = new byte[8192];
        Arrays.fill(plaintext, (byte) 0xCD);

        final byte[] ciphertext = encryptor.encrypt(plaintext);
        final byte[] recovered = encryptor.decrypt(ciphertext);

        assertArrayEquals(plaintext, recovered);
    }

    // ── Non-determinism ─────────────────────────────────────────────────────

    @Test
    void encrypt_isNonDeterministic_differentCiphertextEachTime() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = "non-deterministic".getBytes();

        final byte[] ct1 = encryptor.encrypt(plaintext);
        final byte[] ct2 = encryptor.encrypt(plaintext);

        assertFalse(Arrays.equals(ct1, ct2),
                "Same plaintext must produce different ciphertext (random IV)");
    }

    // ── Ciphertext expansion ────────────────────────────────────────────────

    @Test
    void encrypt_ciphertextIs28BytesLongerThanPlaintext() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = "measure expansion".getBytes();

        final byte[] ciphertext = encryptor.encrypt(plaintext);

        assertEquals(plaintext.length + 28, ciphertext.length,
                "Ciphertext must be exactly 28 bytes longer (12 IV + 16 tag)");
    }

    @Test
    void encrypt_emptyPlaintext_ciphertextIs28Bytes() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);

        final byte[] ciphertext = encryptor.encrypt(new byte[0]);

        assertEquals(28, ciphertext.length,
                "Empty plaintext produces 28-byte ciphertext (IV + tag)");
    }

    // ── Wrong key ───────────────────────────────────────────────────────────

    @Test
    void decrypt_wrongKey_throwsSecurityException() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = "secret data".getBytes();
        final byte[] ciphertext = encryptor.encrypt(plaintext);

        try (final EncryptionKeyHolder otherKey = EncryptionKeyHolder.of(key256Alt())) {
            final AesGcmEncryptor otherEncryptor = new AesGcmEncryptor(otherKey);
            assertThrows(SecurityException.class, () -> otherEncryptor.decrypt(ciphertext),
                    "Decryption with wrong key must throw SecurityException");
        }
    }

    // ── Tampered ciphertext ─────────────────────────────────────────────────

    @Test
    void decrypt_tamperedCiphertext_throwsSecurityException() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        final byte[] plaintext = "tamper test".getBytes();
        final byte[] ciphertext = encryptor.encrypt(plaintext);

        // Flip a byte in the encrypted data portion (after the 12-byte IV)
        ciphertext[14] ^= 0xFF;

        assertThrows(SecurityException.class, () -> encryptor.decrypt(ciphertext),
                "Tampered ciphertext must throw SecurityException");
    }

    // ── Input validation ────────────────────────────────────────────────────

    @Test
    void encrypt_nullPlaintext_throwsNullPointerException() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        assertThrows(NullPointerException.class, () -> encryptor.encrypt(null));
    }

    @Test
    void decrypt_nullCiphertext_throwsNullPointerException() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        assertThrows(NullPointerException.class, () -> encryptor.decrypt(null));
    }

    @Test
    void decrypt_ciphertextTooShort_throwsIllegalArgumentException() {
        final AesGcmEncryptor encryptor = new AesGcmEncryptor(keyHolder);
        assertThrows(IllegalArgumentException.class,
                () -> encryptor.decrypt(new byte[27]));
    }

    @Test
    void constructor_rejects512BitKey() {
        final byte[] bigKey = new byte[64];
        Arrays.fill(bigKey, (byte) 0x42);
        try (final EncryptionKeyHolder holder512 = EncryptionKeyHolder.of(bigKey)) {
            assertThrows(IllegalArgumentException.class, () -> new AesGcmEncryptor(holder512));
        }
    }
}

package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import jlsm.table.internal.BoldyrevaOpeEncryptor;
import jlsm.table.internal.EncryptionKeyHolder;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;

/**
 * Tests for {@link BoldyrevaOpeEncryptor}: order-preserving encryption via hypergeometric sampling.
 */
class BoldyrevaOpeEncryptorTest {

    private static final long DOMAIN = 100;
    private static final long RANGE = 10_000;

    private EncryptionKeyHolder keyHolder;

    private static byte[] key256() {
        final byte[] key = new byte[32];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 1);
        }
        return key;
    }

    private static byte[] key256Alt() {
        final byte[] key = new byte[32];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 0x80);
        }
        return key;
    }

    @BeforeEach
    void setUp() {
        keyHolder = EncryptionKeyHolder.of(key256());
    }

    @AfterEach
    void tearDown() {
        keyHolder.close();
    }

    // ── Round-trip ──────────────────────────────────────────────────────────

    @Test
    void encryptDecrypt_roundTrip() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);

        for (long p = 1; p <= 20; p++) {
            final long ct = encryptor.encrypt(p);
            final long recovered = encryptor.decrypt(ct);
            assertEquals(p, recovered, "Round-trip failed for plaintext " + p);
        }
    }

    @Test
    void encryptDecrypt_boundaryValues() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);

        final long ctFirst = encryptor.encrypt(1);
        assertEquals(1, encryptor.decrypt(ctFirst));

        final long ctLast = encryptor.encrypt(DOMAIN);
        assertEquals(DOMAIN, encryptor.decrypt(ctLast));
    }

    // ── Order preservation ──────────────────────────────────────────────────

    @Test
    void encrypt_preservesOrder() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);

        long prevCt = Long.MIN_VALUE;
        for (long p = 1; p <= DOMAIN; p++) {
            final long ct = encryptor.encrypt(p);
            assertTrue(ct > prevCt,
                    "Order not preserved: encrypt(" + (p - 1) + ")=" + prevCt
                            + " >= encrypt(" + p + ")=" + ct);
            prevCt = ct;
        }
    }

    // ── Determinism ─────────────────────────────────────────────────────────

    @Test
    void encrypt_isDeterministic_sameKey() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);

        final long ct1 = encryptor.encrypt(42);
        final long ct2 = encryptor.encrypt(42);

        assertEquals(ct1, ct2, "Same key and plaintext must produce same ciphertext");
    }

    // ── Different key ───────────────────────────────────────────────────────

    @Test
    void encrypt_differentKey_producesDifferentCiphertext() {
        final BoldyrevaOpeEncryptor enc1 =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
        final long ct1 = enc1.encrypt(50);

        try (final EncryptionKeyHolder otherKey = EncryptionKeyHolder.of(key256Alt())) {
            final BoldyrevaOpeEncryptor enc2 =
                    new BoldyrevaOpeEncryptor(otherKey, DOMAIN, RANGE);
            final long ct2 = enc2.encrypt(50);

            assertNotEquals(ct1, ct2,
                    "Different keys should produce different ciphertext");
        }
    }

    // ── Ciphertext range ────────────────────────────────────────────────────

    @Test
    void encrypt_ciphertextWithinRange() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);

        for (long p = 1; p <= DOMAIN; p++) {
            final long ct = encryptor.encrypt(p);
            assertTrue(ct >= 1 && ct <= RANGE,
                    "Ciphertext " + ct + " out of range [1.." + RANGE + "]");
        }
    }

    // ── Input validation ────────────────────────────────────────────────────

    @Test
    void encrypt_plaintextBelowDomain_throwsIllegalArgumentException() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
        assertThrows(IllegalArgumentException.class, () -> encryptor.encrypt(0));
    }

    @Test
    void encrypt_plaintextAboveDomain_throwsIllegalArgumentException() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
        assertThrows(IllegalArgumentException.class, () -> encryptor.encrypt(DOMAIN + 1));
    }

    @Test
    void decrypt_ciphertextBelowRange_throwsIllegalArgumentException() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
        assertThrows(IllegalArgumentException.class, () -> encryptor.decrypt(0));
    }

    @Test
    void decrypt_ciphertextAboveRange_throwsIllegalArgumentException() {
        final BoldyrevaOpeEncryptor encryptor =
                new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
        assertThrows(IllegalArgumentException.class, () -> encryptor.decrypt(RANGE + 1));
    }

    @Test
    void constructor_rejectsRangeNotGreaterThanDomain() {
        assertThrows(IllegalArgumentException.class,
                () -> new BoldyrevaOpeEncryptor(keyHolder, 100, 100));
    }

    @Test
    void constructor_rejectsRangeSmallerThanDomain() {
        assertThrows(IllegalArgumentException.class,
                () -> new BoldyrevaOpeEncryptor(keyHolder, 100, 50));
    }

    @Test
    void constructor_rejectsZeroDomain() {
        assertThrows(IllegalArgumentException.class,
                () -> new BoldyrevaOpeEncryptor(keyHolder, 0, 100));
    }
}

package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import jlsm.table.internal.DcpeSapEncryptor;
import jlsm.table.internal.EncryptionKeyHolder;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;

/**
 * Tests for {@link DcpeSapEncryptor}: distance-comparison-preserving encryption (Scale-And-Perturb).
 */
class DcpeSapEncryptorTest {

    private static final int DIMS = 8;

    private EncryptionKeyHolder keyHolder;

    private static byte[] key256() {
        final byte[] key = new byte[32];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) (i + 1);
        }
        return key;
    }

    @BeforeEach
    void setUp() {
        keyHolder = EncryptionKeyHolder.of(key256());
    }

    @AfterEach
    void tearDown() {
        keyHolder.close();
    }

    private static float[] vector(float... values) {
        return values;
    }

    private static double l2Distance(float[] a, float[] b) {
        assert a.length == b.length;
        double sum = 0.0;
        for (int i = 0; i < a.length; i++) {
            final double d = a[i] - b[i];
            sum += d * d;
        }
        return Math.sqrt(sum);
    }

    // ── Round-trip ──────────────────────────────────────────────────────────

    @Test
    void encryptDecrypt_roundTrip() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);

        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);
        final float[] recovered = encryptor.decrypt(ev.values(), ev.seed());

        assertArrayEquals(original, recovered, 1e-4f,
                "Decrypted vector must match original within floating-point tolerance");
    }

    @Test
    void encryptDecrypt_roundTrip_zeroVector() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        final float[] original = new float[DIMS];

        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);
        final float[] recovered = encryptor.decrypt(ev.values(), ev.seed());

        assertArrayEquals(original, recovered, 1e-4f);
    }

    // ── Dimensionality preservation ─────────────────────────────────────────

    @Test
    void encrypt_preservesDimensionality() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);

        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);

        assertEquals(DIMS, ev.values().length,
                "Encrypted vector must have same dimensionality as input");
    }

    // ── Distance approximate preservation ───────────────────────────────────

    @Test
    void encrypt_approximatelyPreservesDistanceOrdering() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, 3);
        final float[] a = vector(0.0f, 0.0f, 0.0f);
        final float[] b = vector(1.0f, 0.0f, 0.0f);   // close to a
        final float[] c = vector(10.0f, 10.0f, 10.0f); // far from a

        final DcpeSapEncryptor.EncryptedVector ea = encryptor.encrypt(a);
        final DcpeSapEncryptor.EncryptedVector eb = encryptor.encrypt(b);
        final DcpeSapEncryptor.EncryptedVector ec = encryptor.encrypt(c);

        final double distAB = l2Distance(ea.values(), eb.values());
        final double distAC = l2Distance(ea.values(), ec.values());

        assertTrue(distAB < distAC,
                "Encrypted distance(a,b)=" + distAB + " should be < distance(a,c)=" + distAC
                        + " (approximate distance preservation)");
    }

    // ── Non-determinism ─────────────────────────────────────────────────────

    @Test
    void encrypt_differentSeedsPerEncryption() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);

        final DcpeSapEncryptor.EncryptedVector ev1 = encryptor.encrypt(original);
        final DcpeSapEncryptor.EncryptedVector ev2 = encryptor.encrypt(original);

        assertNotEquals(ev1.seed(), ev2.seed(),
                "Each encryption should use a different seed");
        assertFalse(Arrays.equals(ev1.values(), ev2.values()),
                "Different seeds should produce different encrypted values");
    }

    // ── Encrypted vector usable for distance computation ────────────────────

    @Test
    void encryptedVector_hasFloatArrayFormat() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);

        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);

        assertNotNull(ev.values());
        assertEquals(DIMS, ev.values().length);
        // Verify values are finite (usable for distance computation)
        for (final float v : ev.values()) {
            assertTrue(Float.isFinite(v), "Encrypted value must be finite: " + v);
        }
    }

    // ── Input validation ────────────────────────────────────────────────────

    @Test
    void encrypt_wrongDimensions_throwsIllegalArgumentException() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        assertThrows(IllegalArgumentException.class,
                () -> encryptor.encrypt(new float[DIMS + 1]));
    }

    @Test
    void encrypt_nullVector_throwsNullPointerException() {
        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
        assertThrows(NullPointerException.class, () -> encryptor.encrypt(null));
    }

    @Test
    void constructor_rejectsZeroDimensions() {
        assertThrows(IllegalArgumentException.class,
                () -> new DcpeSapEncryptor(keyHolder, 0));
    }

    @Test
    void constructor_rejectsNegativeDimensions() {
        assertThrows(IllegalArgumentException.class,
                () -> new DcpeSapEncryptor(keyHolder, -1));
    }
}

package jlsm.table.internal;

import java.security.GeneralSecurityException;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.Objects;

import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

/**
 * Contract: Opaque encryption using AES-GCM with a random IV per encryption. Provides authenticated
 * encryption — tampering or wrong-key decryption is detected via tag verification. No search
 * capability on encrypted values.
 *
 * <p>
 * Ciphertext format: {@code [12-byte IV || ciphertext || 16-byte auth tag]} — +28 bytes expansion.
 *
 * <p>
 * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 */
public final class AesGcmEncryptor {

    private static final int IV_LENGTH = 12;
    private static final int TAG_BITS = 128;
    private static final int TAG_BYTES = TAG_BITS / 8;
    private static final int OVERHEAD = IV_LENGTH + TAG_BYTES;
    private static final String ALGORITHM = "AES/GCM/NoPadding";

    private final byte[] keyBytes;
    private final SecureRandom random;

    /**
     * Creates an AES-GCM encryptor using the given key holder.
     *
     * @param keyHolder the key holder providing a 256-bit (32-byte) key
     * @throws IllegalArgumentException if key length is not 32 bytes
     */
    public AesGcmEncryptor(EncryptionKeyHolder keyHolder) {
        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
        if (keyHolder.keyLength() != 32) {
            throw new IllegalArgumentException(
                    "AES-GCM requires a 256-bit (32-byte) key, got " + keyHolder.keyLength());
        }
        this.keyBytes = keyHolder.getKeyBytes();
        this.random = new SecureRandom();
    }

    /**
     * Encrypts the plaintext with AES-GCM using a random IV.
     *
     * @param plaintext the data to encrypt; must not be null
     * @return the ciphertext as {@code [12-byte IV || encrypted bytes || 16-byte tag]}
     */
    public byte[] encrypt(byte[] plaintext) {
        Objects.requireNonNull(plaintext, "plaintext must not be null");
        try {
            final byte[] iv = new byte[IV_LENGTH];
            random.nextBytes(iv);

            final Cipher cipher = Cipher.getInstance(ALGORITHM);
            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, "AES");
            final GCMParameterSpec gcmSpec = new GCMParameterSpec(TAG_BITS, iv);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec);

            final byte[] encrypted = cipher.doFinal(plaintext);
            // encrypted = ciphertext || tag (GCM appends the tag)
            assert encrypted.length == plaintext.length + TAG_BYTES
                    : "GCM output length mismatch";

            final byte[] result = new byte[IV_LENGTH + encrypted.length];
            System.arraycopy(iv, 0, result, 0, IV_LENGTH);
            System.arraycopy(encrypted, 0, result, IV_LENGTH, encrypted.length);
            return result;
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES-GCM encryption failed", e);
        }
    }

    /**
     * Decrypts AES-GCM ciphertext and verifies the authentication tag.
     *
     * @param ciphertext the data to decrypt (IV || encrypted || tag); must not be null
     * @return the plaintext bytes
     * @throws IllegalArgumentException if ciphertext is too short
     * @throws SecurityException if authentication tag verification fails
     */
    public byte[] decrypt(byte[] ciphertext) {
        Objects.requireNonNull(ciphertext, "ciphertext must not be null");
        if (ciphertext.length < OVERHEAD) {
            throw new IllegalArgumentException(
                    "Ciphertext too short: minimum " + OVERHEAD + " bytes, got "
                            + ciphertext.length);
        }
        try {
            final byte[] iv = Arrays.copyOfRange(ciphertext, 0, IV_LENGTH);
            final byte[] encrypted = Arrays.copyOfRange(ciphertext, IV_LENGTH, ciphertext.length);

            final Cipher cipher = Cipher.getInstance(ALGORITHM);
            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, "AES");
            final GCMParameterSpec gcmSpec = new GCMParameterSpec(TAG_BITS, iv);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec);

            return cipher.doFinal(encrypted);
        } catch (javax.crypto.AEADBadTagException e) {
            throw new SecurityException("AES-GCM authentication failed: wrong key or tampered data",
                    e);
        } catch (GeneralSecurityException e) {
            throw new SecurityException("AES-GCM decryption failed", e);
        }
    }
}

package jlsm.table.internal;

import java.security.GeneralSecurityException;
import java.util.Arrays;
import java.util.Objects;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

/**
 * Contract: Deterministic encryption using AES-SIV (RFC 5297). A 512-bit key is split into K1 (CMAC
 * key) and K2 (CTR key). S2V derives a synthetic IV from the plaintext and optional associated
 * data; AES-CTR encrypts the plaintext under that IV. The same plaintext + associated data always
 * produces the same ciphertext, enabling equality queries on encrypted values.
 *
 * <p>
 * Ciphertext format: {@code [16-byte IV || ciphertext]} — +16 bytes expansion.
 *
 * <p>
 * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 */
public final class AesSivEncryptor {

    private static final int BLOCK_SIZE = 16;
    private static final int KEY_512_BYTES = 64;

    /** K1: first 32 bytes — used for CMAC (AES-256-CMAC). */
    private final byte[] cmacKey;
    /** K2: last 32 bytes — used for AES-CTR encryption. */
    private final byte[] ctrKey;

    /**
     * Creates an AES-SIV encryptor using the given key holder.
     *
     * @param keyHolder the key holder providing a 512-bit (64-byte) key
     * @throws IllegalArgumentException if key length is not 64 bytes
     */
    public AesSivEncryptor(EncryptionKeyHolder keyHolder) {
        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
        if (keyHolder.keyLength() != KEY_512_BYTES) {
            throw new IllegalArgumentException(
                    "AES-SIV requires a 512-bit (64-byte) key, got " + keyHolder.keyLength());
        }
        final byte[] fullKey = keyHolder.getKeyBytes();
        this.cmacKey = Arrays.copyOfRange(fullKey, 0, 32);
        this.ctrKey = Arrays.copyOfRange(fullKey, 32, 64);
        Arrays.fill(fullKey, (byte) 0);
    }

    /**
     * Encrypts the plaintext deterministically with optional associated data.
     *
     * @param plaintext the data to encrypt; must not be null
     * @param associatedData optional associated data for IV derivation; may be null
     * @return the ciphertext as {@code [16-byte IV || encrypted bytes]}
     */
    public byte[] encrypt(byte[] plaintext, byte[] associatedData) {
        Objects.requireNonNull(plaintext, "plaintext must not be null");
        final byte[] ad = associatedData != null ? associatedData : new byte[0];

        final byte[] iv = s2v(ad, plaintext);
        final byte[] encrypted = aesCtr(ctrKey, iv, plaintext);

        final byte[] result = new byte[BLOCK_SIZE + encrypted.length];
        System.arraycopy(iv, 0, result, 0, BLOCK_SIZE);
        System.arraycopy(encrypted, 0, result, BLOCK_SIZE, encrypted.length);
        return result;
    }

    /**
     * Decrypts AES-SIV ciphertext and verifies the synthetic IV.
     *
     * @param ciphertext the data to decrypt (IV || encrypted bytes); must not be null
     * @param associatedData the associated data used during encryption; may be null
     * @return the plaintext bytes
     * @throws IllegalArgumentException if ciphertext is too short
     * @throws SecurityException if IV verification fails (wrong key or tampered data)
     */
    public byte[] decrypt(byte[] ciphertext, byte[] associatedData) {
        Objects.requireNonNull(ciphertext, "ciphertext must not be null");
        if (ciphertext.length < BLOCK_SIZE) {
            throw new IllegalArgumentException(
                    "Ciphertext too short: minimum " + BLOCK_SIZE + " bytes, got "
                            + ciphertext.length);
        }
        final byte[] ad = associatedData != null ? associatedData : new byte[0];

        final byte[] iv = Arrays.copyOfRange(ciphertext, 0, BLOCK_SIZE);
        final byte[] encrypted = Arrays.copyOfRange(ciphertext, BLOCK_SIZE, ciphertext.length);
        final byte[] plaintext = aesCtr(ctrKey, iv, encrypted);

        // Verify: recompute S2V and check it matches the extracted IV
        final byte[] recomputedIv = s2v(ad, plaintext);
        if (!Arrays.equals(iv, recomputedIv)) {
            throw new SecurityException(
                    "AES-SIV IV verification failed: wrong key or tampered data");
        }
        return plaintext;
    }

    // ── S2V (RFC 5297 Section 2.4) ──────────────────────────────────────────

    /**
     * S2V: computes the synthetic IV from associated data and plaintext.
     * With one AD string S1 and plaintext Sn:
     *   D = CMAC(K, <zero>)
     *   D = dbl(D) XOR CMAC(K, S1)    [for AD]
     *   if len(Sn) >= 128:
     *     T = Sn xorend D
     *   else:
     *     T = dbl(D) XOR pad(Sn)
     *   return CMAC(K, T)
     */
    private byte[] s2v(byte[] ad, byte[] plaintext) {
        // D = CMAC(zero block)
        byte[] d = cmac(cmacKey, new byte[BLOCK_SIZE]);

        // Process AD: D = dbl(D) XOR CMAC(ad)
        d = dbl(d);
        final byte[] cmacAd = cmac(cmacKey, ad);
        xorInPlace(d, cmacAd);

        // Process plaintext (Sn)
        final byte[] t;
        if (plaintext.length >= BLOCK_SIZE) {
            // T = Sn xorend D — XOR D into the last 16 bytes of Sn
            t = Arrays.copyOf(plaintext, plaintext.length);
            final int offset = t.length - BLOCK_SIZE;
            for (int i = 0; i < BLOCK_SIZE; i++) {
                t[offset + i] ^= d[i];
            }
        } else {
            // T = dbl(D) XOR pad(Sn)
            d = dbl(d);
            t = pad(plaintext);
            xorInPlace(t, d);
        }

        return cmac(cmacKey, t);
    }

    // ── CMAC (RFC 4493) via AES/ECB ─────────────────────────────────────────

    /**
     * AES-CMAC per RFC 4493, implemented using AES/ECB/NoPadding.
     */
    private static byte[] cmac(byte[] key, byte[] message) {
        try {
            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
            final SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
            aes.init(Cipher.ENCRYPT_MODE, keySpec);

            // Generate subkeys K1, K2
            final byte[] l = aes.doFinal(new byte[BLOCK_SIZE]);
            final byte[] k1 = dbl(l);
            final byte[] k2 = dbl(k1);

            final int n = (message.length + BLOCK_SIZE - 1) / BLOCK_SIZE;
            final boolean completeBlock = message.length > 0 && (message.length % BLOCK_SIZE == 0);
            final int blocks = Math.max(n, 1);

            // Process all blocks except the last with CBC-MAC
            final byte[] x = new byte[BLOCK_SIZE];
            for (int i = 0; i < blocks - 1; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    x[j] ^= message[i * BLOCK_SIZE + j];
                }
                final byte[] enc = aes.doFinal(x);
                System.arraycopy(enc, 0, x, 0, BLOCK_SIZE);
            }

            // Last block: XOR with K1 or K2
            final byte[] lastBlock;
            if (completeBlock) {
                lastBlock = Arrays.copyOfRange(message, (blocks - 1) * BLOCK_SIZE,
                        blocks * BLOCK_SIZE);
                xorInPlace(lastBlock, k1);
            } else {
                // Pad incomplete block: append 10*
                lastBlock = new byte[BLOCK_SIZE];
                final int lastStart = (blocks - 1) * BLOCK_SIZE;
                final int remaining = message.length - lastStart;
                if (remaining > 0) {
                    System.arraycopy(message, lastStart, lastBlock, 0, remaining);
                }
                lastBlock[remaining] = (byte) 0x80;
                // rest already 0x00
                xorInPlace(lastBlock, k2);
            }

            xorInPlace(x, lastBlock);
            return aes.doFinal(x);
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES-CMAC computation failed", e);
        }
    }

    // ── AES-CTR encryption ──────────────────────────────────────────────────

    /**
     * AES-CTR encryption/decryption. Per RFC 5297, the counter is derived from the SIV
     * with bits 63 and 31 cleared.
     */
    private static byte[] aesCtr(byte[] key, byte[] iv, byte[] input) {
        if (input.length == 0) {
            return new byte[0];
        }
        try {
            // Clear bits 63 and 31 of the IV to form the initial counter
            final byte[] ctr = Arrays.copyOf(iv, BLOCK_SIZE);
            ctr[8] &= 0x7F;
            ctr[12] &= 0x7F;

            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
            final SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
            aes.init(Cipher.ENCRYPT_MODE, keySpec);

            final byte[] output = new byte[input.length];
            final int fullBlocks = input.length / BLOCK_SIZE;
            final int remainder = input.length % BLOCK_SIZE;

            for (int i = 0; i < fullBlocks; i++) {
                final byte[] keystream = aes.doFinal(ctr);
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    output[i * BLOCK_SIZE + j] = (byte) (input[i * BLOCK_SIZE + j] ^ keystream[j]);
                }
                incrementCounter(ctr);
            }

            if (remainder > 0) {
                final byte[] keystream = aes.doFinal(ctr);
                final int offset = fullBlocks * BLOCK_SIZE;
                for (int j = 0; j < remainder; j++) {
                    output[offset + j] = (byte) (input[offset + j] ^ keystream[j]);
                }
            }

            return output;
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES-CTR encryption failed", e);
        }
    }

    // ── Utility ─────────────────────────────────────────────────────────────

    /** Doubles a block in GF(2^128) with the irreducible polynomial 0x87. */
    private static byte[] dbl(byte[] input) {
        assert input.length == BLOCK_SIZE : "dbl input must be 16 bytes";
        final byte[] result = new byte[BLOCK_SIZE];
        final int carry = (input[0] & 0x80) != 0 ? 0x87 : 0x00;
        for (int i = 0; i < BLOCK_SIZE - 1; i++) {
            result[i] = (byte) (((input[i] & 0xFF) << 1) | ((input[i + 1] & 0x80) >>> 7));
        }
        result[BLOCK_SIZE - 1] = (byte) (((input[BLOCK_SIZE - 1] & 0xFF) << 1) ^ carry);
        return result;
    }

    /** Pads a message shorter than BLOCK_SIZE: append 0x80 then zeros. */
    private static byte[] pad(byte[] input) {
        assert input.length < BLOCK_SIZE : "pad called on full-length input";
        final byte[] padded = new byte[BLOCK_SIZE];
        System.arraycopy(input, 0, padded, 0, input.length);
        padded[input.length] = (byte) 0x80;
        return padded;
    }

    /** XORs src into dst in place: dst[i] ^= src[i]. */
    private static void xorInPlace(byte[] dst, byte[] src) {
        assert dst.length == src.length : "xorInPlace arrays must be same length";
        for (int i = 0; i < dst.length; i++) {
            dst[i] ^= src[i];
        }
    }

    /** Increments a 16-byte big-endian counter. */
    private static void incrementCounter(byte[] ctr) {
        for (int i = BLOCK_SIZE - 1; i >= 0; i--) {
            if (++ctr[i] != 0) {
                break;
            }
        }
    }
}

package jlsm.table.internal;

import java.nio.ByteBuffer;
import java.security.GeneralSecurityException;
import java.util.Objects;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

/**
 * Contract: Order-preserving encryption using the Boldyreva scheme with hypergeometric sampling.
 * Stateless and key-only — no mutable state required. Maps a plaintext domain {@code [1..M]} to a
 * ciphertext range {@code [1..N]} where {@code N >> M}, preserving ordering: if {@code a < b} then
 * {@code encrypt(a) < encrypt(b)}.
 *
 * <p>
 * Uses recursive bisection with key-seeded pseudorandom coin from AES-based PRF to sample from
 * the hypergeometric distribution, mapping each plaintext to a unique ciphertext preserving order.
 *
 * <p>
 * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 */
public final class BoldyrevaOpeEncryptor {

    private static final int MAX_RECURSION_DEPTH = 128;

    private final byte[] keyBytes;
    private final long domainSize;
    private final long rangeSize;

    /**
     * Creates a Boldyreva OPE encryptor with the given key and domain/range configuration.
     *
     * @param keyHolder the key holder providing key material
     * @param domainSize the plaintext domain size M (values in [1..M])
     * @param rangeSize the ciphertext range size N (values in [1..N], must be {@code > domainSize})
     * @throws IllegalArgumentException if rangeSize is not greater than domainSize, or domainSize < 1
     */
    public BoldyrevaOpeEncryptor(EncryptionKeyHolder keyHolder, long domainSize, long rangeSize) {
        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
        if (domainSize < 1) {
            throw new IllegalArgumentException("domainSize must be >= 1, got " + domainSize);
        }
        if (rangeSize <= domainSize) {
            throw new IllegalArgumentException(
                    "rangeSize must be > domainSize, got rangeSize=" + rangeSize
                            + " domainSize=" + domainSize);
        }
        this.keyBytes = keyHolder.getKeyBytes();
        this.domainSize = domainSize;
        this.rangeSize = rangeSize;
    }

    /**
     * Encrypts a plaintext value, preserving order.
     *
     * @param plaintext the value to encrypt; must be in {@code [1..domainSize]}
     * @return the encrypted value in {@code [1..rangeSize]}
     * @throws IllegalArgumentException if plaintext is out of domain bounds
     */
    public long encrypt(long plaintext) {
        if (plaintext < 1 || plaintext > domainSize) {
            throw new IllegalArgumentException(
                    "Plaintext must be in [1.." + domainSize + "], got " + plaintext);
        }
        return encryptRecursive(plaintext, 1, domainSize, 1, rangeSize, 0);
    }

    /**
     * Decrypts a ciphertext value via binary search.
     *
     * @param ciphertext the encrypted value; must be in {@code [1..rangeSize]}
     * @return the original plaintext in {@code [1..domainSize]}
     * @throws IllegalArgumentException if ciphertext is out of range bounds
     */
    public long decrypt(long ciphertext) {
        if (ciphertext < 1 || ciphertext > rangeSize) {
            throw new IllegalArgumentException(
                    "Ciphertext must be in [1.." + rangeSize + "], got " + ciphertext);
        }
        // Binary search: find plaintext p such that encrypt(p) == ciphertext
        long lo = 1;
        long hi = domainSize;
        while (lo <= hi) {
            final long mid = lo + (hi - lo) / 2;
            final long enc = encrypt(mid);
            if (enc == ciphertext) {
                return mid;
            } else if (enc < ciphertext) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        throw new IllegalArgumentException(
                "No plaintext maps to ciphertext " + ciphertext + " in the configured domain/range");
    }

    // ── Recursive bisection (Boldyreva lazy-sample) ─────────────────────────

    /**
     * Recursively maps plaintext m in [dLo..dHi] to ciphertext in [rLo..rHi].
     * At each step, pick midpoint of the range, sample a "coin" from HG distribution
     * to decide how many domain values fall in the left half, then recurse into the
     * appropriate half.
     */
    private long encryptRecursive(long plaintext, long dLo, long dHi, long rLo, long rHi,
            int depth) {
        assert dLo <= dHi : "domain lo > hi";
        assert rLo <= rHi : "range lo > hi";
        assert depth <= MAX_RECURSION_DEPTH : "max recursion depth exceeded at " + depth;

        final long dSize = dHi - dLo + 1;
        final long rSize = rHi - rLo + 1;

        if (dSize == 1) {
            // Single domain value — map to midpoint of remaining range
            return rLo + rSize / 2;
        }

        // Midpoint of range
        final long rMid = rLo + (rSize - 1) / 2;
        final long rLeftSize = rMid - rLo + 1;

        // Sample how many domain values land in the left half [rLo..rMid]
        // using HG(rSize, dSize, rLeftSize) seeded by key + (dLo, dHi, rLo, rHi)
        final long dLeftCount = sampleHypergeometric(rSize, dSize, rLeftSize, dLo, dHi, rLo, rHi);

        if (plaintext <= dLo + dLeftCount - 1) {
            // Plaintext is in the left partition
            return encryptRecursive(plaintext, dLo, dLo + dLeftCount - 1, rLo, rMid, depth + 1);
        } else {
            // Plaintext is in the right partition
            return encryptRecursive(plaintext, dLo + dLeftCount, dHi, rMid + 1, rHi, depth + 1);
        }
    }

    /**
     * Samples from the hypergeometric distribution HG(N, K, n) using an AES-based PRF coin.
     *
     * Population N = rangeSegmentSize, success states K = domainSegmentSize,
     * draws n = leftRangeSize.
     *
     * Returns the number of domain values that fall in the left range partition.
     * Uses the sequential sampling algorithm (Fisher-Yates style).
     */
    private long sampleHypergeometric(long popN, long succK, long draws, long dLo, long dHi,
            long rLo, long rHi) {
        assert popN > 0 : "population must be positive";
        assert succK >= 0 && succK <= popN : "succK out of bounds";
        assert draws >= 0 && draws <= popN : "draws out of bounds";

        // Derive a deterministic seed for this particular node from key + parameters
        final long nodeSeed = prfSeed(dLo, dHi, rLo, rHi);

        // Sequential sampling: iterate through draws, each time flipping a coin
        long population = popN;
        long successes = succK;
        long selected = 0;
        long coinState = nodeSeed;

        for (long i = 0; i < draws && successes > 0; i++) {
            // Probability of selecting a success: successes / population
            // Use PRF coin to decide
            coinState = prfNext(coinState, i);
            final double threshold = (double) successes / (double) population;
            final double coin = pseudoUniform(coinState);

            if (coin < threshold) {
                selected++;
                successes--;
            }
            population--;
        }

        return selected;
    }

    /**
     * Derives a deterministic seed from the key and node parameters using AES encryption.
     */
    private long prfSeed(long dLo, long dHi, long rLo, long rHi) {
        try {
            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, 0,
                    Math.min(keyBytes.length, 32), "AES");
            aes.init(Cipher.ENCRYPT_MODE, keySpec);

            final ByteBuffer buf = ByteBuffer.allocate(16);
            buf.putInt((int) (dLo ^ (dLo >>> 32)));
            buf.putInt((int) (dHi ^ (dHi >>> 32)));
            buf.putInt((int) (rLo ^ (rLo >>> 32)));
            buf.putInt((int) (rHi ^ (rHi >>> 32)));

            final byte[] encrypted = aes.doFinal(buf.array());
            return ByteBuffer.wrap(encrypted).getLong();
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES PRF failed", e);
        }
    }

    /**
     * Derives the next PRF state from current state and iteration.
     */
    private long prfNext(long state, long iteration) {
        try {
            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, 0,
                    Math.min(keyBytes.length, 32), "AES");
            aes.init(Cipher.ENCRYPT_MODE, keySpec);

            final ByteBuffer buf = ByteBuffer.allocate(16);
            buf.putLong(state);
            buf.putLong(iteration);

            final byte[] encrypted = aes.doFinal(buf.array());
            return ByteBuffer.wrap(encrypted).getLong();
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES PRF failed", e);
        }
    }

    /**
     * Maps a long to a pseudo-uniform double in [0, 1).
     */
    private static double pseudoUniform(long value) {
        return (double) (value >>> 1) / (double) Long.MAX_VALUE;
    }
}

package jlsm.table.internal;

import java.nio.ByteBuffer;
import java.security.SecureRandom;
import java.util.Objects;
import java.util.Random;

/**
 * Contract: Distance-comparison-preserving encryption using Scale-And-Perturb (SAP). Encrypts a
 * {@code float[]} vector to a {@code float[]} of the same dimensionality, approximately preserving
 * distance relationships so that existing HNSW/IVF indexes work on encrypted vectors.
 *
 * <p>
 * Encryption: {@code c = s * v + noise}, where {@code s} is a scaling factor derived from the key
 * and {@code noise} is sampled from a d-ball using a per-vector perturbation seed. Decryption
 * requires the stored seed to reconstruct the noise vector.
 *
 * <p>
 * Governed by: .kb/algorithms/encryption/vector-encryption-approaches.md
 */
public final class DcpeSapEncryptor {

    private final double scaleFactor;
    private final int dimensions;
    private final byte[] keyBytes;
    private final SecureRandom seedRng;

    /**
     * Creates a DCPE Scale-And-Perturb encryptor with the given key.
     *
     * @param keyHolder the key holder providing key material
     * @param dimensions the expected vector dimensionality; must be positive
     * @throws IllegalArgumentException if dimensions is not positive
     */
    public DcpeSapEncryptor(EncryptionKeyHolder keyHolder, int dimensions) {
        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
        if (dimensions <= 0) {
            throw new IllegalArgumentException("dimensions must be positive, got " + dimensions);
        }
        this.dimensions = dimensions;
        this.keyBytes = keyHolder.getKeyBytes();

        // Derive scaling factor from key: hash first 8 bytes to a positive double in [1.5, 3.5)
        final long keyLong = ByteBuffer.wrap(keyBytes, 0, 8).getLong();
        this.scaleFactor = 1.5 + 2.0 * ((double) (keyLong >>> 1) / (double) Long.MAX_VALUE);
        assert scaleFactor >= 1.5 && scaleFactor < 3.5 : "scaleFactor out of expected range";

        // Seed RNG from remaining key bytes for generating per-vector seeds
        this.seedRng = new SecureRandom(keyBytes);
    }

    /**
     * Encrypts a plaintext vector, preserving approximate distance relationships.
     *
     * @param vector the plaintext vector; must have length equal to configured dimensions
     * @return the encrypted vector and its perturbation seed
     * @throws IllegalArgumentException if vector length does not match dimensions
     */
    public EncryptedVector encrypt(float[] vector) {
        Objects.requireNonNull(vector, "vector must not be null");
        if (vector.length != dimensions) {
            throw new IllegalArgumentException(
                    "Vector length must be " + dimensions + ", got " + vector.length);
        }

        final long seed = seedRng.nextLong();
        final float[] noise = generateNoise(seed);

        final float[] encrypted = new float[dimensions];
        for (int i = 0; i < dimensions; i++) {
            encrypted[i] = (float) (scaleFactor * vector[i]) + noise[i];
        }

        return new EncryptedVector(encrypted, seed);
    }

    /**
     * Decrypts an encrypted vector using the stored perturbation seed.
     *
     * @param encrypted the encrypted vector values
     * @param seed the perturbation seed stored during encryption
     * @return the reconstructed plaintext vector
     */
    public float[] decrypt(float[] encrypted, long seed) {
        Objects.requireNonNull(encrypted, "encrypted must not be null");
        final float[] noise = generateNoise(seed);

        final float[] result = new float[encrypted.length];
        for (int i = 0; i < encrypted.length; i++) {
            result[i] = (float) ((encrypted[i] - noise[i]) / scaleFactor);
        }
        return result;
    }

    /**
     * Generates a noise vector sampled from the d-ball using a deterministic seed.
     * The perturbation radius beta is kept small (0.01) to maintain distance ordering.
     */
    private float[] generateNoise(long seed) {
        final double beta = 0.01;
        final Random rng = new Random(seed);

        // Sample from d-dimensional unit ball using Gaussian method:
        // 1. Sample d Gaussian values
        // 2. Normalize to unit sphere
        // 3. Scale by uniform radius^(1/d) * beta
        final float[] noise = new float[dimensions];
        double normSq = 0.0;
        for (int i = 0; i < dimensions; i++) {
            final double g = rng.nextGaussian();
            noise[i] = (float) g;
            normSq += g * g;
        }

        final double norm = Math.sqrt(normSq);
        if (norm > 0) {
            // Uniform radius in d-ball: r = U^(1/d) * beta
            final double u = rng.nextDouble();
            final double r = Math.pow(u, 1.0 / dimensions) * beta;

            for (int i = 0; i < dimensions; i++) {
                noise[i] = (float) (noise[i] / norm * r);
            }
        }

        return noise;
    }

    /**
     * Holds an encrypted vector alongside the perturbation seed needed for decryption.
     *
     * @param values the encrypted vector components (same dimensionality as plaintext)
     * @param seed the perturbation seed used during encryption
     */
    public record EncryptedVector(float[] values, long seed) {
    }
}

